 "content": "from collections import deque


def transform(grid):
    """Mark inner rims of closed 1-line regions (3) and their exterior halo (2)."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label 4-connected components of the linework.
    comp = [[-1] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or comp[r][c] >= 0:
                continue
            k = len(components)
            cells = []
            q = deque([(r, c)])
            comp[r][c] = k
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and comp[yy][xx] < 0:
                        comp[yy][xx] = k
                        q.append((yy, xx))
            components.append(cells)

    # Zero cells reachable from the edge are outside; the rest are enclosed.
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            y, x = r + dy, c + dx
            if 0 <= y < h and 0 <= x < w and grid[y][x] == 0 and not outside[y][x]:
                outside[y][x] = True
                q.append((y, x))

    active = set()
    enclosed = [[grid[r][c] == 0 and not outside[r][c] for c in range(w)] for r in range(h)]
    for r in range(h):
        for c in range(w):
            if not enclosed[r][c]:
                continue
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                y, x = r + dy, c + dx
                if 0 <= y < h and 0 <= x < w and grid[y][x] == 1:
                    out[r][c] = 3
                    active.add(comp[y][x])

    # Exterior one-cell 8-neighbor halo, only for components enclosing a cavity.
    for k in active:
        for r, c in components[k]:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    y, x = r + dy, c + dx
                    if 0 <= y < h and 0 <= x < w and grid[y][x] == 0 and outside[y][x]:
                        out[y][x] = 2
    return out
